-- 0032: the therapist site moves to https://therapists.mindpillars.app
-- (repository Reagandennis/mindpillars-therapists, served from the ops
-- server). Safe to run more than once.
--
-- 1. Emails and messages that point therapists at the site now use the new
--    address: the invitation, approval and decline emails, the payout email,
--    and the "hasn't signed the agreement" message admins see. Each function
--    is its latest definition (0028, 0029, 0031) with only the address
--    changed. Generated by build_0032.py from those bodies.
-- 2. therapist_list_sessions() also returns client_key: the same value for
--    every session a therapist has with one client, so the site can group
--    sessions into clients. It is a hash of the therapist and the client, so
--    it tells the therapist nothing about who the client is, and it differs
--    between therapists. The app ignores the extra column.
--
-- Before running: Supabase → Authentication → URL Configuration → add
-- https://therapists.mindpillars.app/** to Redirect URLs (and set the Site
-- URL to https://therapists.mindpillars.app), or sign-in links won't come
-- back to the new site.

begin;

-- notify_therapist_invited: as in 0028_therapist_applications.sql, with the new address.
create or replace function public.notify_therapist_invited()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  care_team constant text := 'reagan.e.owiti@gmail.com';
  site constant text := 'https://therapists.mindpillars.app/';
  therapist_name text;
begin
  if tg_op = 'UPDATE' and new.email = old.email then
    return new;
  end if;
  select t.full_name into therapist_name
    from public.therapists t where t.id = new.therapist_id;
  perform public.send_app_email(
    new.email,
    care_team,
    'You’ve been added as a therapist',
    public.email_layout(
      'Sign in with this email to see your sessions.',
      'Welcome to the care team',
      'Hi ' || public.email_escape(split_part(coalesce(therapist_name, ''), ' ', 1))
        || ', you’ve been added as a therapist on Δεν είσαι μόνος.',
      public.email_box('#F6F6F6', 'Getting started',
        '<div style="font-size:12.5px;line-height:1.55;color:#6E6E73;">'
        || 'Sign in at <a href="' || site || '">therapists.mindpillars.app</a> with '
        || '<strong style="font-weight:600;color:#191919;">'
        || public.email_escape(new.email) || '</strong> — with Google, or with a '
        || 'password and the confirmation email. You’ll see your sessions, take '
        || 'each video call in the browser, and keep your profile up to date. '
        || 'Your sessions are also in the app, under '
        || '<strong style="font-weight:600;color:#191919;">Settings → My therapy sessions</strong>.</div>'),
      'Questions? Just reply to this email.'
    ),
    'Hi ' || split_part(coalesce(therapist_name, ''), ' ', 1) || ','
      || E'\n\n'
      || 'You’ve been added as a therapist on Δεν είσαι μόνος. Sign in at '
      || site || ' with ' || new.email || ' (Google, or a password and the '
      || 'confirmation email) to see your sessions, take each video call in the '
      || 'browser and keep your profile up to date. Your sessions are also in '
      || 'the app, under Settings → My therapy sessions.',
    'therapist-invite/' || new.therapist_id || '/' || md5(new.email)
  );
  return new;
end;
$$;

-- admin_review_therapist_application: as in 0029_therapist_kyc.sql, with the new address.
create or replace function public.admin_review_therapist_application(
  p_id uuid,
  p_approve boolean,
  p_reason text default null,
  p_checks text[] default '{}'
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  care_team constant text := 'reagan.e.owiti@gmail.com';
  app public.therapist_applications%rowtype;
  therapist uuid;
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_missing text[];
  v_checks jsonb;
begin
  if not public.is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  select * into app from public.therapist_applications where id = p_id for update;
  if not found then
    raise exception 'That application no longer exists.' using errcode = 'P0002';
  end if;
  if app.status <> 'pending' then
    raise exception 'That application has already been reviewed.' using errcode = '22023';
  end if;

  select coalesce(jsonb_object_agg(k, jsonb_build_object(
           'by', public.current_user_email(), 'at', now())), '{}')
    into v_checks
    from unnest(public.kyc_check_keys()) k
    where k = any (coalesce(p_checks, '{}'));

  if coalesce(p_approve, false) then
    if app.kyc_confirmed_at is null or app.id_front_path is null
       or app.selfie_path is null or app.licence_path is null then
      raise exception 'This application has no identity documents. Decline it and ask them to send it again with their ID, selfie and licence.'
        using errcode = '22023';
    end if;
    select array_agg(k) into v_missing
      from unnest(public.kyc_check_keys()) k
      where not (k = any (coalesce(p_checks, '{}')));
    if v_missing is not null then
      raise exception 'Tick every check before you approve.' using errcode = '22023';
    end if;
    if app.licence_expires_on is null or app.licence_expires_on <= current_date then
      raise exception 'Their licence has expired. Decline and ask for a current practising certificate.'
        using errcode = '22023';
    end if;
    if exists (select 1 from public.therapist_accounts ta where ta.email = app.email) then
      raise exception 'A therapist already signs in with %. Link them on the Therapists page instead.', app.email
        using errcode = '23505';
    end if;
    insert into public.therapists (
      full_name, title, credentials, bio, specialties, languages,
      years_experience, photo_url, licence_expires_on, active
    )
    values (
      app.full_name, app.title,
      left(app.credentials || ' · Licence ' || app.licence_number || ' (' || app.licence_body || ')', 200),
      app.bio, app.specialties, app.languages, app.years_experience,
      app.photo_url, app.licence_expires_on, true
    )
    returning id into therapist;
    insert into public.therapist_accounts (therapist_id, email)
    values (therapist, app.email);
    update public.therapist_applications
    set status = 'approved', therapist_id = therapist, kyc_checks = v_checks,
        reviewed_by = public.current_user_email(), reviewed_at = now(),
        updated_at = now()
    where id = p_id;
    return therapist;
  end if;

  update public.therapist_applications
  set status = 'declined', decline_reason = v_reason, kyc_checks = v_checks,
      reviewed_by = public.current_user_email(), reviewed_at = now(),
      updated_at = now()
  where id = p_id;
  perform public.send_app_email(
    app.email,
    care_team,
    'About your application to the care team',
    public.email_layout(
      'An update on your application.',
      'About your application',
      'Hi ' || public.email_escape(split_part(app.full_name, ' ', 1))
        || ', thank you for applying to join the care team on Δεν είσαι μόνος. '
        || 'We can’t approve your application as it stands.',
      case when v_reason is null then '' else
        public.email_box('#F6F6F6', 'What we need',
          '<div style="font-size:12.5px;line-height:1.55;color:#6E6E73;">'
          || replace(public.email_escape(v_reason), E'\n', '<br>') || '</div>')
      end,
      'You can update your application and send it again at '
        || '<a href="https://therapists.mindpillars.app/">therapists.mindpillars.app</a>. '
        || 'Questions? Just reply to this email.'
    ),
    'Hi ' || split_part(app.full_name, ' ', 1) || ',' || E'\n\n'
      || 'Thank you for applying to join the care team on Δεν είσαι μόνος. '
      || 'We can’t approve your application as it stands.'
      || coalesce(E'\n\n' || v_reason, '') || E'\n\n'
      || 'You can update it and send it again at https://therapists.mindpillars.app/',
    'therapist-application-declined/' || p_id || '/' || extract(epoch from now())::bigint
  );
  return null;
end;
$$;

-- therapy_requests_agreement_check: as in 0031_rates_earnings_agreement.sql, with the new address.
create or replace function public.therapy_requests_agreement_check()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text;
  v_name text;
begin
  if new.status = 'confirmed' and new.therapist_id is not null
     and (old.status is distinct from 'confirmed'
          or old.therapist_id is distinct from new.therapist_id) then
    select ta.email, t.full_name into v_email, v_name
      from public.therapists t
      left join public.therapist_accounts ta on ta.therapist_id = t.id
     where t.id = new.therapist_id;
    if v_email is null or public.therapist_accepted_agreement(v_email) is null then
      raise exception '% hasn’t accepted the therapist agreement yet, so they can’t be given sessions. Ask them to sign in at therapists.mindpillars.app and accept it.',
        coalesce(v_name, 'This therapist') using errcode = 'P0001';
    end if;
  end if;
  return new;
end;
$$;

-- admin_record_therapist_payout: as in 0031_rates_earnings_agreement.sql, with the new address.
create or replace function public.admin_record_therapist_payout(
  p_therapist_id uuid,
  p_currency text,
  p_method text,
  p_reference text default null,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  care_team constant text := 'reagan.e.owiti@gmail.com';
  v_id uuid;
  v_total bigint;
  v_count integer;
  v_email text;
  v_name text;
  v_label text;
  v_ref text := nullif(trim(coalesce(p_reference, '')), '');
  v_method text := case p_method when 'mpesa' then 'M-Pesa' when 'bank' then 'bank transfer'
                     when 'paypal' then 'PayPal' when 'wise' then 'Wise' else 'payment' end;
begin
  if not public.is_admin() then
    raise exception 'Admins only' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtext('therapist_payout:' || p_therapist_id::text));
  select sum(r.therapist_fee_minor), count(*) into v_total, v_count
    from public.therapy_requests r
   where r.therapist_id = p_therapist_id and r.status = 'completed'
     and r.payout_id is null and r.therapist_fee_currency = upper(p_currency);
  if coalesce(v_count, 0) = 0 then
    raise exception 'Nothing is owed to them in %.', upper(p_currency) using errcode = '22023';
  end if;
  insert into public.therapist_payouts (therapist_id, currency, amount_minor, session_count, method, reference, note, created_by)
  values (p_therapist_id, upper(p_currency), v_total, v_count, p_method, v_ref,
          nullif(trim(coalesce(p_note, '')), ''), public.current_user_email())
  returning id into v_id;
  update public.therapy_requests r
  set payout_id = v_id
  where r.therapist_id = p_therapist_id and r.status = 'completed'
    and r.payout_id is null and r.therapist_fee_currency = upper(p_currency);

  select ta.email, t.full_name into v_email, v_name
    from public.therapists t
    left join public.therapist_accounts ta on ta.therapist_id = t.id
   where t.id = p_therapist_id;
  v_label := public.therapy_price_label(v_total, upper(p_currency));
  if v_email is not null then
    perform public.send_app_email(
      v_email,
      care_team,
      'We’ve paid you ' || v_label,
      public.email_layout(
        'Your payment for ' || v_count || ' session' || case when v_count = 1 then '' else 's' end || '.',
        'You’ve been paid',
        'Hi ' || public.email_escape(split_part(coalesce(v_name, ''), ' ', 1))
          || ', we’ve sent you ' || public.email_escape(v_label) || ' by ' || v_method
          || ' for ' || v_count || ' session' || case when v_count = 1 then '' else 's' end || '.',
        public.email_box('#F3F6FC', 'Payment',
          '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">'
          || public.email_row('Amount', public.email_escape(v_label))
          || public.email_row('Sessions', v_count::text)
          || public.email_row('Sent by', v_method)
          || coalesce(public.email_row('Reference', public.email_escape(v_ref)), '')
          || '</table>'),
        'Every session it covers is listed under Earnings at '
          || '<a href="https://therapists.mindpillars.app/">therapists.mindpillars.app</a>. '
          || 'Questions? Just reply to this email.'
      ),
      'Hi ' || split_part(coalesce(v_name, ''), ' ', 1) || ',' || E'\n\n'
        || 'We’ve sent you ' || v_label || ' by ' || v_method || ' for ' || v_count
        || ' session' || case when v_count = 1 then '' else 's' end || '.'
        || coalesce(E'\n' || 'Reference: ' || v_ref, '') || E'\n\n'
        || 'Every session it covers is listed under Earnings at https://therapists.mindpillars.app/',
      'therapist-payout/' || v_id
    );
  end if;
  return v_id;
end;
$$;

-- therapist_list_sessions: as in 0016, plus client_key.
drop function if exists public.therapist_list_sessions();
create function public.therapist_list_sessions()
returns table (
  id uuid,
  status text,
  topic text,
  availability text[],
  note text,
  scheduled_at timestamptz,
  duration_minutes smallint,
  payment_status text,
  is_free_session boolean,
  client_first_name text,
  client_summary text,
  completed_at timestamptz,
  close_reason text,
  client_joined_at timestamptz,
  my_rating smallint,
  my_comment text,
  my_flags text[],
  client_key text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  me uuid := public.current_therapist_id();
begin
  if me is null then
    raise exception 'Therapists only' using errcode = '42501';
  end if;
  return query
  select r.id, r.status, r.topic, r.availability, r.note, r.scheduled_at,
         r.duration_minutes, r.payment_status, r.is_free_session,
         public.therapy_client_first_name(r.user_id),
         r.client_summary, r.completed_at,
         r.close_reason, r.client_joined_at,
         tr.rating, tr.comment, tr.flags,
         left(md5(me::text || ':' || r.user_id::text), 16)
  from public.therapy_requests r
  left join public.therapy_ratings tr
    on tr.request_id = r.id and tr.author_role = 'therapist'
  where r.therapist_id = me
    and r.status in ('confirmed', 'completed', 'cancelled')
  order by r.scheduled_at desc nulls last
  limit 300;
end;
$$;
revoke execute on function public.therapist_list_sessions() from public, anon;
grant execute on function public.therapist_list_sessions() to authenticated;

commit;
